module tb;
    // Declare inputs as regs, outputs as wires
    reg  [5:0] y;
    reg        w;
    wire       Y1;
    wire       Y3;

    // Instantiate TopModule dut
    TopModule dut (
        .y  (y),
        .w  (w),
        .Y1 (Y1),
        .Y3 (Y3)
    );

    integer errors = 0;
    integer i;

    // Task to check expected outputs
    task check_outputs(input [5:0] state, input bit in_w, input exp_Y1, input exp_Y3);
        begin
            y = state;
            w = in_w;
            #5; // Allow combinatorial propagation

            if (Y1 !== exp_Y1) begin
                $display("Mismatch: y=6'b%b, w=%b | Y1=%b (Expected %b)", y, w, Y1, exp_Y1);
                errors = errors + 1;
