            if (Y3 !== exp_Y3) begin
                $display("Mismatch: y=6'b%b, w=%b | Y3=%b (Expected %b)", y, w, Y3, exp_Y3);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        y = 6'b000000;
        w = 1'b0;
        #10;

